const sampleStats = (g, N) => {
  const xs = Array.from({ length: N }, () => g.mvnormal(D.MEAN2, D.COV2));
  const mean = Num.scale(xs.reduce((a, x) => Num.add(a, x), [0, 0]), 1 / N);
  let C = Num.zeros(2, 2);
  for (const x of xs) C = Num.add(C, Num.outer(Num.sub(x, mean), Num.sub(x, mean)));
  return [mean, Num.scale(C, 1 / (N - 1))];
};
